<script setup lang="ts">
import {ref,computed,watch} from 'vue';
const props=defineProps<{accounts:any[]}>();
const selectedKey=ref(''),search=ref(''),root=ref(''),kind=ref(''),expanded=ref(new Set<string>());
const selected=computed(()=>props.accounts.find(a=>a.key===selectedKey.value));
const byKey=computed(()=>new Map<string,any>(props.accounts.map(a=>[a.key,a])));
const filtering=computed(()=>!!(search.value||root.value||kind.value));
function matches(a:any){return (!root.value||a.root_type===root.value)&&(!kind.value||(kind.value==='group')===a.is_group)&&(!search.value||[a.code,a.name,a.currency,a.account_type,...(a.contributors||[]).map((c:any)=>c.company_name)].join(' ').toLowerCase().includes(search.value.toLowerCase()));}
const rows=computed(()=>{const allowed=new Set<string>();for(const a of props.accounts.filter(matches)){let cursor=a;while(cursor&&!allowed.has(cursor.key)){allowed.add(cursor.key);cursor=byKey.value.get(cursor.parent_key);}}
 const children=new Map<string|null,any[]>();for(const a of props.accounts){const parent=byKey.value.has(a.parent_key)?a.parent_key:null;children.set(parent,[...(children.get(parent)||[]),a]);}
 const result:any[]=[],seen=new Set<string>();function walk(parent:string|null,depth:number,guides:boolean[]=[]){const siblings=(children.get(parent)||[]).filter(a=>allowed.has(a.key));siblings.forEach((a,index)=>{if(seen.has(a.key))return;seen.add(a.key);const last=index===siblings.length-1,hasChildren=!!children.get(a.key)?.length;result.push({account:a,depth,last,hasChildren,guides:guides.slice(1)});if(filtering.value||expanded.value.has(a.key))walk(a.key,depth+1,[...guides,!last]);});}walk(null,0);return result;});
const path=computed(()=>{const names:string[]=[],seen=new Set<string>();let a=selected.value;while(a&&!seen.has(a.key)){seen.add(a.key);names.unshift(a.name);a=byKey.value.get(a.parent_key);}return names.join(' / ');});
const amount=(n:any)=>Number(n||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
function expandAll(){expanded.value=new Set(props.accounts.filter(a=>a.is_group).map(a=>a.key));}
function toggle(key:string){const next=new Set(expanded.value);next.has(key)?next.delete(key):next.add(key);expanded.value=next;}
watch(()=>props.accounts,()=>{expandAll();if(!byKey.value.has(selectedKey.value))selectedKey.value='';},{immediate:true});
</script>
<template><section class="ac-combined-chart"><div class="ac-stats"><article><small>Total accounts</small><strong>{{accounts.length}}</strong></article><article><small>Groups</small><strong>{{accounts.filter(a=>a.is_group).length}}</strong></article><article><small>Ledger accounts</small><strong>{{accounts.filter(a=>!a.is_group).length}}</strong></article></div>
<div class="ac-filters"><label class="ac-search">Find an account<input v-model="search" type="search" placeholder="Search by code, name or company"></label><label>Root type<select v-model="root"><option value="">All root types</option><option v-for="type in ['Asset','Liability','Equity','Income','Expense']" :key="type">{{type}}</option></select></label><label>Account kind<select v-model="kind"><option value="">All accounts</option><option value="group">Groups</option><option value="ledger">Ledger accounts</option></select></label><button v-if="filtering" class="button" @click="search='';root='';kind=''">Clear filters</button></div>
<div class="ac-chart-layout has-selection"><section class="ac-tree-panel" :style="{'--tree-width':Math.max(780,620+Math.max(0,...rows.map(r=>r.depth))*24)+'px'}"><header><div><h3>Account hierarchy</h3><small class="muted">Select an account to view its combined balance and company details.</small></div><div class="ac-tree-controls"><button @click="expandAll">Expand all</button><button @click="expanded=new Set()">Collapse all</button></div></header><div class="ac-chart-columns"><span>Account code / name</span><span>Debit</span><span>Credit</span><span>Balance</span><span>Currency</span></div>
<div class="ac-tree" role="tree" aria-label="Combined chart of accounts"><div v-for="row in rows" :key="row.account.key" role="treeitem" :aria-level="row.depth+1" :aria-expanded="row.hasChildren?(filtering||expanded.has(row.account.key)):undefined" :aria-selected="selectedKey===row.account.key" class="ac-tree-row" :class="{selected:selectedKey===row.account.key,group:row.account.is_group,root:!row.account.parent_key}" :style="{'--depth':row.depth}"><span class="ac-tree-connectors" aria-hidden="true"><span v-for="(continues,index) in row.guides" :key="index" v-show="continues" class="ac-tree-guide" :style="{'--guide-level':index}"></span><span v-if="row.depth" class="ac-tree-elbow" :class="{'is-last':row.last}"></span><span v-if="row.hasChildren&&(filtering||expanded.has(row.account.key))" class="ac-tree-stem"></span></span><button v-if="row.hasChildren" class="ac-toggle" :aria-label="(expanded.has(row.account.key)?'Collapse ':'Expand ')+row.account.name" @click="toggle(row.account.key)"><svg viewBox="0 0 20 20" :class="{rotated:filtering||expanded.has(row.account.key)}" aria-hidden="true"><path d="m7 4 6 6-6 6"/></svg></button><span v-else class="ac-toggle-spacer"></span><button class="ac-account" @click="selectedKey=row.account.key"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path :d="row.account.is_group?'M3 6h7l2 2h9v12H3z':'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4'"/></svg><code>{{row.account.code}}</code><span>{{row.account.name}}</span></button><span class="ac-chart-amount">{{amount(row.account.debit)}}</span><span class="ac-chart-amount">{{amount(row.account.credit)}}</span><span class="ac-chart-amount">{{amount(row.account.balance)}} <small>{{row.account.balance_side}}</small></span><span class="ac-chart-state">{{row.account.currency}}</span></div></div><p v-if="!rows.length" class="ac-empty-small">No matching accounts.</p></section>
<aside class="ac-detail" aria-label="Account details"><template v-if="selected"><div class="ac-detail-heading"><span class="ac-badge active">{{selected.currency}}</span><span class="muted">{{selected.is_group?'Group account':'Ledger account'}}</span><button class="ac-detail-close" aria-label="Close account details" @click="selectedKey=''">&#215;</button></div><code class="ac-detail-code">{{selected.code}}</code><h3>{{selected.name}}</h3><p class="ac-path">{{path}}</p><dl><div><dt>Combined debit</dt><dd>{{amount(selected.debit)}}</dd></div><div><dt>Combined credit</dt><dd>{{amount(selected.credit)}}</dd></div><div><dt>Combined balance</dt><dd>{{amount(selected.balance)}} {{selected.balance_side}}</dd></div><div><dt>Account type</dt><dd>{{selected.account_type}}</dd></div></dl><h4>Company contributions</h4><div v-for="source in selected.contributors" :key="source.company_id" class="ac-company-contribution"><a :href="source.url">{{source.company_name}}</a><span>{{amount(source.balance)}} {{source.balance_side}} {{selected.currency}}</span><small>Debit {{amount(source.debit)}} / Credit {{amount(source.credit)}}</small></div></template><template v-else><p class="eyebrow">ACCOUNT DETAILS</p><h3>A place for every account</h3><p class="muted">Select an account in the hierarchy to see its combined amounts and the companies behind it.</p></template></aside></div></section></template>
<style scoped>.ac-combined-chart .ac-stats{grid-template-columns:repeat(3,minmax(0,1fr));margin:20px 0}.ac-combined-chart .ac-detail{min-width:0}.ac-company-contribution{display:flex;flex-direction:column;gap:7px;padding:12px 0;border-bottom:1px solid var(--line);font-size:12px}.ac-company-contribution small{color:var(--muted)}@media(max-width:650px){.ac-combined-chart .ac-stats{grid-template-columns:1fr}}
</style>
